139	\begin{theorem}[Quantum soundness of the simultaneous classical low individual degree test]\label{lem:ld-soundness}
140		\lean{MIPStarRE.QPBT.deltaLd, MIPStarRE.QPBT.exists_ld_soundness}
141		\leanok
142		\uses{def:ld-game, def:ld-question-distribution, def:ld-win-predicate, def:ld-meas, def:projective-strategy-general, def:tensor-product-value, def:consistency, def:bracket}
143		There exists a function
144		\[
145			\delta_{\mathrm{ld}}(\eps, q, m, d, k) = a\,(dmk)^a \bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)
146		\]
147		for universal constants $a \ge 1$ and $0 < b \le 1$ such that the following holds. For all $\eps > 0$ and every parameter tuple $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game} (so $m, d, k \ge 1$, $q$ is an admissible field size, and $m$ divides $q$), and for all projective strategies $(\psi, A, B)$ that succeed with probability at least $1-\eps$ in the game $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$, there exist measurements
148		\[
149			G^w \in \mathrm{PolyMeas}(m,q,d,k)
150		\]
151		on $\hilb_w$ for $w \in \{\mathrm A,\mathrm B\}$, where by slight abuse of notation $m$, $q$, $d$ denote the constant tuples $(m,\ldots,m)$, $(q,\ldots,q)$, $(d,\ldots,d)$ of length $k$, such that
152		\begin{align*}
153			A^{\mathsf{Point},\, u}_{a_1,\ldots,a_k} \ot I_{\mathrm B}
154			&\simeq_{\delta_{\mathrm{ld}}}
155			I_{\mathrm A} \ot G^{\mathrm B}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]}\;,\\
156			G^{\mathrm A}_{[(g_1(u),\ldots,g_k(u)) = (a_1,\ldots,a_k)]} \ot I_{\mathrm B}
157			&\simeq_{\delta_{\mathrm{ld}}}
158			I_{\mathrm A} \ot B^{\mathsf{Point},\, u}_{a_1,\ldots,a_k}\;,\\
159			G^{\mathrm A}_{g_1,\ldots,g_k} \ot I_{\mathrm B}
160			&\simeq_{\delta_{\mathrm{ld}}}
161			I_{\mathrm A} \ot G^{\mathrm B}_{g_1,\ldots,g_k}\;,
162		\end{align*}
163		where $\delta_{\mathrm{ld}} = \delta_{\mathrm{ld}}(\eps,q,m,d,k)$, all three relations are the state-dependent consistency $\simeq$ of Definition~\ref{def:consistency} with respect to the state $\ket{\psi}$, and the bracket notation for post-processed outcomes is that of Definition~\ref{def:bracket}. The first two relations hold on average over the uniform distribution on $u \in \F_q^m$; no question distribution is associated with the third.
164	\end{theorem}
